def switch_sim(num_ports, frames):
    BROADCAST = "ff:ff:ff:ff:ff:ff"
    table = {}
    out = []
    for port, src, dst in frames:
        if src != BROADCAST:
            table[src] = port
        if dst == BROADCAST or dst not in table:
            out.append([p for p in range(num_ports) if p != port])
        elif table[dst] == port:
            out.append([])
        else:
            out.append([table[dst]])
    return out

net-nat-table.solution:
def nat_sim(public_ip, first_port, packets):
    out_map, in_map, allowed = {}, {}, set()
    next_port = first_port
    res = []
    for pkt in packets:
        if pkt[0] == "out":
            _, sip, sport, dip, dport = pkt
            key = (sip, sport)
            if key not in out_map:
                out_map[key] = next_port
                in_map[next_port] = key
                next_port += 1
            pub = out_map[key]
            allowed.add((pub, dip, dport))
            res.append([public_ip, pub, dip, dport])
        else:
            _, sip, sport, dport = pkt
            if dport in in_map and (dport, sip, sport) in allowed:
                res.append(list(in_map[dport]))
            else:
                res.append("drop")
    return res

net-traceroute-hops.solution:
def reconstruct_path(replies, dest):
    if not replies:
        return []
    by_ttl = {}
    for ttl, ip, rtt in replies:
        by_ttl.setdefault(ttl, {}).setdefault(ip, []).append(rtt)
    reached = [t for t in by_ttl if dest in by_ttl[t]]
    last = min(reached) if reached else max(by_ttl)
    path = []
    for t in range(1, last + 1):
        if t not in by_ttl:
            path.append(["*", -1])
            continue
        ips = by_ttl[t]
        ip = min(ips, key=lambda k: (-len(ips[k]), k))
        path.append([ip, min(ips[ip])])
    return path

net-dns-resolver.solution:
def resolve(records, queries):
    zone = {name: (typ, ttl, val) for name, typ, ttl, val in records}
    cache = {}
    out = []
    for now, name in queries:
        lookups = 0
        cur = name
        hops = 0
        while True:
            ent = cache.get(cur)
            if ent is not None and now < ent[2]:
                typ, val = ent[0], ent[1]
            else:
                lookups += 1
                if cur not in zone:
                    ans = "NXDOMAIN"
                    break
                typ, ttl, val = zone[cur]
                cache[cur] = (typ, val, now + ttl)
            if typ == "A":
                ans = val
                break
            hops += 1
            if hops > 8:
                ans = "SERVFAIL"
                break
            cur = val
        out.append([ans, lookups])
    return out

net-http-parse.solution:
def parse_http(raw):
    head, _, body = raw.partition("\r\n\r\n")
    lines = head.split("\r\n")
    start = lines[0]
    headers = {}
    for line in lines[1:]:
        if not line:
            continue
        name, _, value = line.partition(":")
        name = name.strip().lower()
        value = value.strip(" \t")
        if name in headers:
            headers[name] = headers[name] + ", " + value
        else:
            headers[name] = value
    if "content-length" in headers:
        body = body[:int(headers["content-length"])]
    if start.startswith("HTTP/"):
        parts = start.split(" ", 2)
        reason = parts[2] if len(parts) > 2 else ""
        return ["response", parts[0], int(parts[1]), reason, headers, body]
    method, target, version = start.split(" ")
    return ["request", method, target, version, headers, body]

net-chunked-decode.solution:
def decode_chunked(data):
    i = 0
    out = []
    while True:
        j = data.index("\r\n", i)
        size = int(data[i:j].split(";")[0].strip(), 16)
        i = j + 2
        if size == 0:
            break
        out.append(data[i:i + size])
        i += size + 2
    return "".join(out)

net-cache-freshness.solution:
def cache_decision(headers, age, shared):
    d = {}
    for part in headers.get("cache-control", "").split(","):
        part = part.strip().lower()
        if not part:
            continue
        k, _, v = part.partition("=")
        d[k.strip()] = v.strip().strip('"')
    if "no-store" in d:
        return "no-store"
    if shared and "private" in d:
        return "no-store"
    if "no-cache" in d:
        return "revalidate"
    if shared and "s-maxage" in d:
        life = int(d["s-maxage"])
    elif "max-age" in d:
        life = int(d["max-age"])
    elif "expires" in headers and "date" in headers:
        life = max(0, headers["expires"] - headers["date"])
    else:
        life = 0
    if age < life:
        return "fresh"
    if "must-revalidate" in d or (shared and "proxy-revalidate" in d):
        return "revalidate"
    if "stale-while-revalidate" in d and age < life + int(d["stale-while-revalidate"]):
        return "stale-while-revalidate"
    return "revalidate"

net-cookie-match.solution:
def cookies_to_send(set_cookies, request):
    jar = {}
    order = 0
    for host, header in set_cookies:
        host = host.lower()
        parts = header.split(";")
        name, _, value = parts[0].partition("=")
        name = name.strip()
        value = value.strip()
        domain = None
        path = "/"
        secure = False
        delete = False
        for attr in parts[1:]:
            k, _, v = attr.partition("=")
            k = k.strip().lower()
            v = v.strip()
            if k == "domain" and v:
                if v.startswith("."):
                    v = v[1:]
                domain = v.lower()
            elif k == "path":
                path = v if v.startswith("/") else "/"
            elif k == "secure":
                secure = True
            elif k == "max-age":
                delete = int(v) <= 0
        if domain is None:
            host_only = True
            domain = host
        else:
            host_only = False
            if not (host == domain or host.endswith("." + domain)):
                continue
        key = (name, domain, path)
        if delete:
            jar.pop(key, None)
            continue
        if key in jar:
            seq = jar[key][0]
        else:
            seq = order
            order += 1
        jar[key] = (seq, value, host_only, secure)
    scheme, rhost, rpath = request
    rhost = rhost.lower()
    chosen = []
    for (name, domain, path), (seq, value, host_only, secure) in jar.items():
        if host_only:
            if rhost != domain:
                continue
        elif not (rhost == domain or rhost.endswith("." + domain)):
            continue
        if secure and scheme != "https":
            continue
        if rpath != path:
            if not rpath.startswith(path):
                continue
            if not (path.endswith("/") or rpath[len(path)] == "/"):
                continue
        chosen.append((-len(path), seq, name + "=" + value))
    chosen.sort()
    return "; ".join(c[2] for c in chosen)

net-url-normalize.solution:
def normalize_url(url):
    UNRESERVED = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~")

    def pct(s):
        out = []
        i = 0
        while i < len(s):
            if s[i] == "%":
                hx = s[i + 1:i + 3].upper()
                ch = chr(int(hx, 16))
                out.append(ch if ch in UNRESERVED else "%" + hx)
                i += 3
            else:
                out.append(s[i])
                i += 1
        return "".join(out)

    url = url.split("#", 1)[0]
    scheme, rest = url.split("://", 1)
    scheme = scheme.lower()
    cut = len(rest)
    for ch in "/?":
        k = rest.find(ch)
        if k != -1:
            cut = min(cut, k)
    authority, tail = rest[:cut], rest[cut:]
    path, _, query = tail.partition("?")
    host, _, port = authority.partition(":")
    host = host.lower()
    if port and not ((scheme == "http" and port == "80") or (scheme == "https" and port == "443")):
        host += ":" + port
    path = pct(path)
    query = pct(query)
    if path == "":
        path = "/"
    segs = path.split("/")[1:]
    out = []
    for idx, seg in enumerate(segs):
        last = idx == len(segs) - 1
        if seg == ".":
            if last:
                out.append("")
        elif seg == "..":
            if out:
                out.pop()
            if last:
                out.append("")
        else:
            out.append(seg)
    path = "/" + "/".join(out)
    return scheme + "://" + host + path + ("?" + query if query else "")

net-hpack-toy.solution:
STATIC = [(":method", "GET"), (":method", "POST"), (":path", "/"), (":scheme", "https"),
          (":status", "200"), ("accept-encoding", "gzip, deflate"), ("content-type", ""), ("user-agent", "")]


def hpack_encode(headers, max_entries):
    dyn = []
    out = []
    for name, value in headers:
        table = STATIC + dyn
        full = None
        name_idx = None
        for i, (n, v) in enumerate(table, 1):
            if n == name:
                if name_idx is None:
                    name_idx = i
                if v == value:
                    full = i
                    break
        if full is not None:
            out.append(["I", full])
            continue
        if name_idx is not None:
            out.append(["N", name_idx, value])
        else:
            out.append(["L", name, value])
        if max_entries > 0:
            dyn.insert(0, (name, value))
            del dyn[max_entries:]
    return out

net-websocket-frame.solution:
def decode_frame(data):
    if len(data) < 2:
        return []
    fin = bool(data[0] & 0x80)
    opcode = data[0] & 0x0F
    masked = bool(data[1] & 0x80)
    length = data[1] & 0x7F
    pos = 2
    if length == 126:
        if len(data) < 4:
            return []
        length = (data[2] << 8) | data[3]
        pos = 4
    elif length == 127:
        if len(data) < 10:
            return []
        length = 0
        for b in data[2:10]:
            length = (length << 8) | b
        pos = 10
    key = []
    if masked:
        if len(data) < pos + 4:
            return []
        key = data[pos:pos + 4]
        pos += 4
    if len(data) < pos + length:
        return []
    payload = data[pos:pos + length]
    if masked:
        payload = [b ^ key[i % 4] for i, b in enumerate(payload)]
    return [fin, opcode, masked, length, payload]

net-lb-weighted-round-robin.solution:
def weighted_round_robin(weights, n):
    if not weights:
        return []
    total = sum(weights)
    cur = [0] * len(weights)
    out = []
    for _ in range(n):
        best = 0
        for i, w in enumerate(weights):
            cur[i] += w
            if cur[i] > cur[best]:
                best = i
        cur[best] -= total
        out.append(best)
    return out

net-lb-least-connections.solution:
def least_connections(num_servers, events):
    active = [0] * num_servers
    healthy = [True] * num_servers
    where = {}
    out = []
    for kind, x in events:
        if kind == "req":
            best = -1
            for s in range(num_servers):
                if healthy[s] and (best == -1 or active[s] < active[best]):
                    best = s
            if best != -1:
                active[best] += 1
                where[x] = best
            out.append(best)
        elif kind == "done":
            if x in where:
                active[where.pop(x)] -= 1
        elif kind == "down":
            healthy[x] = False
        else:
            healthy[x] = True
    return out

net-consistent-hash.solution:
def consistent_hash(servers, replicas, keys):
    def fnv(s):
        h = 2166136261
        for b in s.encode("utf-8"):
            h ^= b
            h = (h * 16777619) & 0xFFFFFFFF
        return h

    ring = sorted((fnv(s + "#" + str(i)), s) for s in servers for i in range(replicas))
    out = []
    for k in keys:
        if not ring:
            out.append("")
            continue
        idx = bisect.bisect_left(ring, (fnv(k), ""))
        if idx == len(ring):
            idx = 0
        out.append(ring[idx][1])
    return out

net-backoff-jitter.solution:
def backoff_schedule(base, cap, attempts, mode, rand):
    out = []
    prev = base
    for i in range(attempts):
        r = rand[i]
        c = min(cap, base * (2 ** i))
        if mode == "none":
            d = c
        elif mode == "full":
            d = c * r // 100
        elif mode == "equal":
            half = c // 2
            d = half + (c - half) * r // 100
        else:
            d = min(cap, base + (3 * prev - base) * r // 100)
            prev = d
        out.append(d)
    return out

net-tcp-handshake-validate.solution:
def tcp_trace_check(segments):
    n = len(segments)
    if n == 0:
        return 0
    s = segments[0]
    if not (s[0] == "C" and s[1] == "SYN" and s[4] == 0):
        return 0
    nxt = {"C": s[2] + 1}
    if n == 1:
        return 1
    s = segments[1]
    if not (s[0] == "S" and s[1] == "SYN+ACK" and s[3] == nxt["C"] and s[4] == 0):
        return 1
    nxt["S"] = s[2] + 1
    if n == 2:
        return 2
    s = segments[2]
    if not (s[0] == "C" and s[1] == "ACK" and s[2] == nxt["C"] and s[3] == nxt["S"] and s[4] == 0):
        return 2
    last_ack = {"C": nxt["S"], "S": nxt["C"]}
    fin = {"C": False, "S": False}
    for i in range(3, n):
        who, flags, seq, ack, ln = segments[i]
        peer = "S" if who == "C" else "C"
        if flags not in ("ACK", "FIN+ACK"):
            return i
        if seq != nxt[who]:
            return i
        if ack > nxt[peer] or ack < last_ack[who]:
            return i
        if fin[who] and (ln > 0 or flags == "FIN+ACK"):
            return i
        nxt[who] += ln
        if flags == "FIN+ACK":
            nxt[who] += 1
            fin[who] = True
        last_ack[who] = ack
    return -1

net-cwnd-evolution.solution:
def cwnd_trace(ssthresh, events):
    cwnd = 1
    out = [cwnd]
    for e in events:
        if e == "ok":
            if cwnd < ssthresh:
                cwnd = min(cwnd * 2, ssthresh)
            else:
                cwnd += 1
        elif e == "3dup":
            ssthresh = max(cwnd // 2, 2)
            cwnd = ssthresh
        else:
            ssthresh = max(cwnd // 2, 2)
            cwnd = 1
        out.append(cwnd)
    return out

net-sliding-window-sender.solution:
def sender_trace(total, window, events):
    base = 0
    nxt = 0
    out = []

    def fill():
        nonlocal nxt
        sent = []
        while nxt < base + window and nxt < total:
            sent.append(nxt)
            nxt += 1
        return sent

    out.append(fill())
    for e in events:
        if e == -1:
            resend = list(range(base, nxt))
            out.append(resend + fill())
        else:
            if base < e <= nxt:
                base = e
            out.append(fill())
    return out

net-gbn-vs-sr.solution:
def gbn_vs_sr(n, window, lost):
    lostset = set((p, a) for p, a in lost)
    att = [0] * n
    base = 0
    g = 0
    while base < n:
        end = min(base + window, n)
        first_lost = None
        for p in range(base, end):
            att[p] += 1
            g += 1
            if first_lost is None and (p, att[p]) in lostset:
                first_lost = p
        base = end if first_lost is None else first_lost
    att = [0] * n
    got = [False] * n
    base = 0
    s = 0
    while base < n:
        for p in range(base, min(base + window, n)):
            if not got[p]:
                att[p] += 1
                s += 1
                if (p, att[p]) not in lostset:
                    got[p] = True
        while base < n and got[base]:
            base += 1
    return [g, s]
